            }
            set('delivery_readback',local.verified===true&&reads.length===outbox.length&&reads.every(x=>x.verified),
                'feishu:GET/'+route.lead,{reads,local_outbox_verified:local.verified,external_write_calls:0});
          } catch {
            set('delivery_readback',null,'feishu:GET/readback',{reason:'external_delivery_unverified',external_write_calls:0});
          }
        }
        result.output.outbox_states=outbox.map(o=>({id:o.id,state:o.state,feishu_record_id:o.feishu_record_id}));
      }
      result.output.comment_ids=ids;
    }
    await client.query('ROLLBACK');
  } catch(error) {
    // No raw exception messages: DB/HTTP exceptions may contain credentials.
    result.output.readback_error=error.code||(/^[A-Z0-9_]+$/.test(error.message)?error.message:'READBACK_UNAVAILABLE');
  } finally {client?.release();if(pool)await pool.end();}
